  "differences": [
    {
      "point": "Britannica describes the festival as being in honour of the cabrii, while Wikipedia describes the Cabeiri as enigmatic chthonic deities.",
      "quote_britannica": "fellirals in honour of the cabrii, celebrated in Thebes and Lemnos",
      "quote_wikipedia": "were a group of enigmatic chthonic deities."
    },
    {
      "point": "Britannica describes an initiation rite involving a throne and riband, whereas Wikipedia states that little is known about the secret initiation ceremonies.",
      "quote_britannica": "The economy of imitation was performed by placing the candidate, crowned with white-hemches, and grilled about the hons with a purple riband, on a kind of throne",
      "quote_wikipedia": "due to the secret nature of mystery cults in the ancient world little survives to indicate what was involved in these initiation ceremonies"
    }
  ],
  "claims": [
    {
      "claim": "The cult was celebrated in Thebes and Lemnos.",
      "tag": "enduring",
      "quote_britannica": "celebrated in Thebes and Lemnos, but especially in Samotbracis",
      "quote_wikipedia": "centered in the north Aegean Islands of Lemnos and possibly Samothrace —at the Samothrace temple complex —and at Thebes."
    },
    {
      "claim": "The cult was especially celebrated in Samothrace.",
      "tag": "enduring",
      "quote_britannica": "celebrated in Thebes and Lemnos, but especially in Samotbracis, an island conferred to the cabin.",
      "quote_wikipedia": "centered in the north Aegean Islands of Lemnos and possibly Samothrace —at the Samothrace temple complex —and at Thebes."
    },
    {
      "claim": "Initiates were thought to be protected from storms at sea and other dangers.",
      "tag": "enduring",
      "quote_britannica": "All who were initiated into the welfare of the fests, gods, were fought to be featured thereby from florms at tea, and all other dangers.",
      "quote_wikipedia": "Samothrace offered an initiatory mystery, which promised safety and prosperity to seamen."
    },
    {
      "claim": "The initiation involved placing a crowned candidate on a throne with a purple riband.",
