  "term_pairs": [
    {
      "old": "cabrii",
      "new": "Cabeiri",
      "quote_britannica": "fellirals in honour of the cabrii, celebrated in Thebes and Lemnos",
      "quote_wikipedia": "In Greek mythology, the Cabeiri or Cabiri / k ə ˈ b aɪ r iː / (Ancient Greek: Κάβειροι, romanized: Kábeiroi)"
    },
    {
      "old": "Samotbracis",
      "new": "Samothrace",
      "quote_britannica": "celebrated in Thebes and Lemnos, but especially in Samotbracis, an island conferred to the cabin.",
      "quote_wikipedia": "centered in the north Aegean Islands of Lemnos and possibly Samothrace —at the Samothrace temple complex —and at Thebes."
    },
    {
      "old": "fests, gods",
      "new": "Cabeiri",
      "quote_britannica": "All who were initiated into the welfare of the fests, gods, were fought to be featured thereby from florms at tea, and all other dangers.",
      "quote_wikipedia": "In Greek mythology, the Cabeiri or Cabiri / k ə ˈ b aɪ r iː / (Ancient Greek: Κάβειροι, romanized: Kábeiroi), also transliterated Kabeiri or Kabiri, were a group of enigmatic chthonic deities."
    }
  ],
  "wiki_only_topics": [
    {
      "topic": "Etymology and proposed linguistic origins of the name Cabeiri",
      "quote_wikipedia": "In the past, the Semitic word kabir (\"great\") has been compared to Κάβειροι since at least Joseph Justus Scaliger in the sixteenth century, but nothing else seemed to point to a Semitic origin, until the idea of \"great\" gods expressed by the Semitic root kbr was definitively attested for North Syria in the thirteenth century BCE, in texts from Emar published by D. Arnaud in 1985–87."
    },
    {
      "topic": "Specific names and genealogies of the Cabeiri",
      "quote_wikipedia": "When represented as a pair of males and a pair of females the Cabeiri's most common names are Axiocersus and Cadmilus for the pair of males and Axierus and Axiocersa for the pair of females."
    },
    {
      "topic": "Comparison with other mythological races such as the Telchines and Cyclopes",
      "quote_wikipedia": "In myth, the Cabeiri bear many similarities to other fabulous races, such as the Telchines of Rhodes, the Cyclopes, the Dactyls, the Korybantes, and the Kuretes."
    },
    {
      "topic": "Archaeological evidence and survival of the Lemnian cult through Hellenization",
      "quote_wikipedia": "In Lemnos the cult of the Cabeiri survived, according to archaeological evidence, through the conquest: an ancient sanctuary dedicated to the Cabeiri is identifiable by traces of inscriptions, and seems to have survived the process of Hellenization."
    },
    {
      "topic": "The Cabeiri at Thebes in Boeotia and associated votive finds",
      "quote_wikipedia": "At Thebes in Boeotia, a sanctuary for the Cabeiri existed some miles east of the city. There are more varied finds than on Lemnos; they include many little bronze votive bulls and which carry on into Roman times, when the traveller Pausanias, always alert to the history of cults, learned that it was Demeter Kabeiriia who instigated the initiation cult there in the name of Prometheus and his son Aitnaios."
    }
  ]
}
